"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4551],{48990:e=>{e.exports=JSON.parse('{"functions":[{"name":"AddExp","desc":"Accrue `amount` BP EXP for a player (from the OnQuestRewardGranted feed). No-op if\\namount <= 0 or the profile is not loaded. Fires OnBattlePassLevelUp when the derived\\nlevel rises, then replicates.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"amount","desc":"","lua_type":"number"},{"name":"_reason","desc":"","lua_type":"string?"}],"returns":[],"function_type":"static","source":{"line":170,"path":"src/ServerStorage/SharedModules/BattlePassManager.luau"}},{"name":"ClaimBattlePass","desc":"Bulk-claim: bank every unlocked-but-unclaimed reward across both rows in one call\\n(Premium only if the player is premium). Idempotent \u2014 flags are set before grants, so\\na re-entrant call finds nothing and returns NOTHING_TO_CLAIM. Returns\\n(ok, reasonCode, freeCount, premiumCount, coinsGranted); counts/coins are 0 on failure.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":195,"path":"src/ServerStorage/SharedModules/BattlePassManager.luau"}},{"name":"GetLevel","desc":"Current derived level (0 if profile not loaded).","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":215,"path":"src/ServerStorage/SharedModules/BattlePassManager.luau"}},{"name":"IsPremium","desc":"Cached premium status (false if unresolved).","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":224,"path":"src/ServerStorage/SharedModules/BattlePassManager.luau"}},{"name":"Initialize","desc":"Wire the profile lifecycle, the packet handlers, the OnQuestRewardGranted EXP feed,\\nthe subscription-prompt-finished hook, and the rollover/premium-refresh tick. Call\\nexactly once per server (from a loader). Safe in both places.","params":[],"returns":[],"function_type":"static","source":{"line":285,"path":"src/ServerStorage/SharedModules/BattlePassManager.luau"}}],"properties":[],"types":[],"name":"BattlePassManager","desc":"Place-agnostic authority for the monthly battle pass. Owns the PlayerBattlePass\\nProfileStore profile (one session per player, key = UserId), accrues EXP, resolves\\npremium via MarketplaceService, validates the bulk claim, runs the monthly rollover\\n+ auto-grant sweep, and replicates via BattlePassStateSync.\\n\\nRuns in BOTH the lobby and gameplay places. BP EXP is fed by the OnQuestRewardGranted\\nsignal (fired by QuestManager); there are no gameplay sources of its own.\\n\\nCross-place: STORE_NAME + tostring(UserId) key are identical in every place, so the\\nsame DataStore record is shared; ProfileStore session-locking serialises the handoff.\\nLevel is never stored \u2014 BattlePassState.levelFromExp derives it. Premium is never\\nstored \u2014 it is live-resolved and cached in-memory per session.","realm":["Server"],"source":{"line":19,"path":"src/ServerStorage/SharedModules/BattlePassManager.luau"}}')}}]);